INSERT INTO actions (action_id, org_id, incident_id, type, target, risk, policy_decision, status, rationale, idempotency_key, requested_at, expires_at, decided_by, decided_at, executed_at, completed_at, result_verified, result_detail) VALUES
  ('b368ab23-7550-5ce7-ba08-2def7779593c', 'fe77357f-d0cc-5345-ada4-f4d6e70e1f4d', 'aa515a77-a1df-584d-b899-f1922598cbee', 'block_ip', '192.168.8.66', 'low', 'ask', 'awaiting_approval', 'This machine guessed the password and delivered the file. Blocking it cuts off the attacker without touching RECEPTION-PC.', 'de107c89eb30ea276c60e4819a209c46f8a6ec4650fed9b5594e3c34ada3ff3c', TIMESTAMPADD(MICROSECOND, -2695000000, @nw_anchor), NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('aa7d9f1b-2a0f-5fd0-a759-bd80a2edd981', 'fe77357f-d0cc-5345-ada4-f4d6e70e1f4d', '8e51f83b-45b3-5477-92be-6fbcc3f84005', 'block_domain', 'ohip-card-renewal.example', 'low', 'auto', 'succeeded', 'The domain is a confirmed phishing page. Blocking a domain is low risk and allowed automatically by your policy.', '920e229cba31ea6e9c3825fb138aac6cae28b1fe65bd9671fe59bd6771514900', TIMESTAMPADD(MICROSECOND, -9895000000, @nw_anchor), NULL, NULL, TIMESTAMPADD(MICROSECOND, -9870000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -9865000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -9830000000, @nw_anchor), TRUE, 'Domain is on the blocklist; a test lookup returned 0.0.0.0.'),
  ('008b7032-8859-546e-b039-b4f7b2b6c202', 'fe77357f-d0cc-5345-ada4-f4d6e70e1f4d', 'fb043a41-32d5-5ac4-a075-78c0e6161290', 'isolate_host', 'DOCTOR-LAPTOP', 'high', 'ask', 'failed', 'Regular check-ins to an unknown address look like remote control. Isolating the laptop stops it while you investigate.', '71736087ea3a827759712cd8f4f0cd7c49340673fe2e28cb21c93cb2c756f4f9', TIMESTAMPADD(MICROSECOND, -6295000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -4495000000, @nw_anchor), 'b9d2c63a-07de-530f-8137-be4ea607ade8', TIMESTAMPADD(MICROSECOND, -5880000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -5875000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -5840000000, @nw_anchor), FALSE, 'Endpoint agent offline; isolation command was not delivered.'),
  ('724efe28-38af-534a-ba61-0d981e2013fe', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', '3f85ff59-ab6b-5bba-82cb-c64951a06718', 'isolate_host', 'FRONTDESK-PC', 'high', 'ask', 'awaiting_approval', 'FRONTDESK-PC is the machine changing the files. Cutting it off the network stops the encryption from spreading.', 'f0a8e6c5c8ea8355ebac55a9720f8b254bf6290d9d23ac633057a61570ee7f8d', TIMESTAMPADD(MICROSECOND, -1495000000, @nw_anchor), NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1ab5e80b-f8f4-53d3-8c5f-6f2e07c6dc9b', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', '3f85ff59-ab6b-5bba-82cb-c64951a06718', 'disable_account', 'frontdesk', 'critical', 'never', 'proposed', 'The changes ran under the ''frontdesk'' account. Your policy says a person must disable accounts, so this is a recommendation.', 'f0b55020063357436255753556622b380dd1856947e6503d8e7ae6dfc45b5ab4', TIMESTAMPADD(MICROSECOND, -1495000000, @nw_anchor), NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('bb31f835-6fd5-5ef0-a011-852ff50d5e98', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', 'fae9922e-1af1-50c7-8c80-bf956bec3f3e', 'block_ip', '203.0.113.45', 'low', 'ask', 'executing', 'The address only tried passwords and has a bad reputation. Blocking it is low risk.', '4d595e9ec2c5e0b95d084fc3bcf59ac45c7b4e633fec29fb93e5c6fe7ccadd7a', TIMESTAMPADD(MICROSECOND, -3295000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -1495000000, @nw_anchor), '1dee0cb7-d4ab-522b-a7b5-83b48ac6766c', TIMESTAMPADD(MICROSECOND, -3000000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -2995000000, @nw_anchor), NULL, NULL, NULL),
  ('f198c962-9169-5e6b-a02c-07314aa6990d', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', '44d6ef55-d171-57ed-9a30-5d63b2cc62ca', 'block_ip', '198.51.100.23', 'low', 'ask', 'denied', 'Unrecognised remote access to a clinical workstation. Blocking stops the session if it is not expected.', '8da6034d15ce3b7c163e94acba4e3cc7d574390d351f441fa5e3cbcdcc26b8d8', TIMESTAMPADD(MICROSECOND, -11695000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -9895000000, @nw_anchor), '56184dab-1d56-59b4-9327-26bc64292f58', TIMESTAMPADD(MICROSECOND, -11040000000, @nw_anchor), NULL, NULL, NULL, NULL),
  ('34f4c8a1-de78-527a-ad39-b14a23ed3b2c', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', '2cb93ca4-3399-5272-acd8-d5d6031fd2da', 'quarantine_file', 'sha256:9f2b6c1e0d4a7b3c8e5f1a2d6b9c0e3f4a7d1b8c2e5f9a0b3c6d8e1f4a7b2c5d', 'high', 'ask', 'approved', 'The file is confirmed malware. Quarantine removes it without touching anything else on the workstation.', 'c4e8a2c70ef614a8ff5c2a9f1a7c1ede3a0acf1e758cbdb85ae3828db7b99fbf', TIMESTAMPADD(MICROSECOND, -5095000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -3295000000, @nw_anchor), '1dee0cb7-d4ab-522b-a7b5-83b48ac6766c', TIMESTAMPADD(MICROSECOND, -4560000000, @nw_anchor), NULL, NULL, NULL, NULL),
  ('48fdcfb7-5db5-5c28-bd89-3204e9fedb64', 'ad03d9e6-2963-5895-8403-2aafc5b0aa68', '2cb93ca4-3399-5272-acd8-d5d6031fd2da', 'block_ip', '198.51.100.77', 'low', 'ask', 'expired', 'The macro tried to download more from this address. Blocking it prevents a second stage.', 'ddd8d57e5c32b8c476f8ac618acf61ad065d5a1c668de88a9b0588486f986ad0', TIMESTAMPADD(MICROSECOND, -5095000000, @nw_anchor), TIMESTAMPADD(MICROSECOND, -3295000000, @nw_anchor), NULL, NULL, NULL, NULL, NULL, NULL),
